import os
import re

def find_pilot_references(root_dir):
    """Search for 'pilot' references in Python files."""
    results = []
    for dirpath, dirnames, filenames in os.walk(root_dir):
        for f in filenames:
            if f.endswith('.py') and 'pilot' not in f.lower():
                filepath = os.path.join(dirpath, f)
                try:
                    with open(filepath, 'r', errors='ignore') as file:
                        content = file.read()
                        if re.search(r'\bpilot\b', content, re.IGNORECASE):
                            results.append(filepath)
                except:
                    pass
    return results

